CREATE DATABASE IF NOT EXISTS swiftbite CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE swiftbite;
CREATE TABLE users(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) UNIQUE NOT NULL,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','restaurant','customer','courier') NOT NULL,is_active TINYINT(1) DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE api_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) UNIQUE NOT NULL,expires_at DATETIME NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE restaurants(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,manager_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,description TEXT,image_url VARCHAR(255),is_active TINYINT(1) DEFAULT 1,FOREIGN KEY(manager_id) REFERENCES users(id));
CREATE TABLE menu_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,restaurant_id BIGINT UNSIGNED NOT NULL,name VARCHAR(150) NOT NULL,description TEXT,price DECIMAL(10,2) NOT NULL,image_url VARCHAR(255),is_available TINYINT(1) DEFAULT 1,FOREIGN KEY(restaurant_id) REFERENCES restaurants(id));
CREATE TABLE orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,customer_id BIGINT UNSIGNED NOT NULL,restaurant_id BIGINT UNSIGNED NOT NULL,courier_id BIGINT UNSIGNED NULL,status ENUM('pending','accepted','preparing','ready','picked_up','delivered','cancelled') DEFAULT 'pending',total_amount DECIMAL(12,2) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(customer_id) REFERENCES users(id),FOREIGN KEY(restaurant_id) REFERENCES restaurants(id),FOREIGN KEY(courier_id) REFERENCES users(id));
CREATE TABLE order_items(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,order_id BIGINT UNSIGNED NOT NULL,restaurant_id BIGINT UNSIGNED NOT NULL,menu_item_id BIGINT UNSIGNED NOT NULL,quantity INT UNSIGNED NOT NULL,unit_price DECIMAL(10,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(restaurant_id) REFERENCES restaurants(id),FOREIGN KEY(menu_item_id) REFERENCES menu_items(id));
